#pragma once

#include <stdint.h>

/* Lookup tables of the solver, generated by tools/rubiktab.c into
 * rubik_tab.c (and, for the assembly, into rubik_tab.S under other names).
 *
 * A state is a permutation rank p (Lehmer code of the seven cubies, 0..5039)
 * and an orientation rank o (base 3 over the first six cubies, 0..728).
 *
 *   rubik_perm[p][f], f < 3   the permutation after a quarter turn of face f
 *                             (R, B, D), as (rank << 3) | dp, where dp is the
 *                             fewest moves that solve the permutation alone
 *   rubik_perm[p][3]          index in rubik_near of the first entry with
 *                             permutation p; row RUBIK_NPERM closes the range
 *   rubik_orient[o][f], f < 3 the same for the orientation, with dor the
 *                             fewest moves that solve the orientation alone
 *   rubik_near                the states within 5 moves of solved and the
 *                             states at distance 11, grouped by permutation
 *                             and sorted by orientation, as (o << 4) | code
 *
 * dp and dor never exceed the true distance, so max(dp, dor) is a lower
 * bound for pruning. A row is 8 bytes, so (rank << 3) is also the byte offset
 * of the next row: the assembly masks the low three bits and indexes with it.
 */
#define RUBIK_NPERM 5040
#define RUBIK_NORIENT 729
#define RUBIK_NNEAR 14868

#define RUBIK_CODE_SOLVED 9 /* the solved state */
#define RUBIK_CODE_FAR 15   /* a state at distance 11 */

extern const uint16_t rubik_perm[RUBIK_NPERM + 1][4];
extern const uint16_t rubik_orient[RUBIK_NORIENT][4];
extern const uint16_t rubik_near[RUBIK_NNEAR];
